def submit_to_google(url, data):
    import requests
    import json
    import os

    return requests.post(
        url,
        data=json.dumps(data),
        headers={
            'Content-Type': 'application/json',
            'Authorization': 'Bearer ' + os.environ['GCP_OAUTH_TOKEN'],
        }
    )


